select m1_0.match_id,m1_0.match_time,s1_0.stage_id,s1_0.name,s1_0.is_regular,ts1_0.team_id,t1_0.team_id,t1_0.code,t2_0.team_id,t2_0.code,ms1_0.set_number,ms1_0.play_time,c1_0.champion_id,c1_0.name,ts1_0.victory,ps1_0.kills,ps1_0.deaths,ps1_0.assists,(ps1_0.minion_kills+ps1_0.monster_kills),ps1_0.damage_to_champions,ps1_0.gold_at_15,ps2_0.gold_at_15,ps1_0.total_points,ps1_0.is_pog from player_set ps1_0 join team_set ts1_0 on ts1_0.team_set_id=ps1_0.team_set_id join match_set ms1_0 on ms1_0.set_id=ts1_0.set_id join lck_match m1_0 on m1_0.match_id=ms1_0.match_id join stage s1_0 on s1_0.stage_id=m1_0.stage_id join team t1_0 on t1_0.team_id=m1_0.team1_id join team t2_0 on t2_0.team_id=m1_0.team2_id join champion c1_0 on c1_0.champion_id=ps1_0.champion_id left join team_set ts2_0 on ts2_0.set_id=ms1_0.set_id and ts2_0.team_id<>ts1_0.team_id left join player_set ps2_0 on ps2_0.team_set_id=ts2_0.team_set_id and ps2_0.position=ps1_0.position where ps1_0.player_id=16507 and m1_0.match_time>='2026-01-01 00:00:00' and m1_0.match_time<'2027-01-01 00:00:00' order by m1_0.match_time desc,m1_0.match_id desc,ms1_0.set_number
